   "id": "zd8350245",
   "sez": "sport",
   "titolo": "Il gol da centrocampo di Diego Gomez illumina il 5-0 del Brighton sul Crystal Palace",
   "orig": "Brighton winger's long-range goal conjures decades-old memories of Beckham",
   "lead": "Il centrocampista Diego Gomez ha segnato un gol spettacolare dalla metà campo, paragonato a quello di David Beckham contro il Wimbledon 30 anni fa, nella netta vittoria per 5-0 del Brighton & Hove Albion sul Crystal Palace in Premier League. L'allenatore Fabian Hürzeler ha elogiato l'impegno del giocatore, mentre il successo prosegue l'ottimo inizio di stagione dei Seagulls. Lo riferiscono The Guardian e Citizen Digital.",
   "more": [
    "Il gol da centrocampo rimanda a quello celebre di David Beckham contro il Wimbledon nel 1996, considerato uno dei più iconici della storia della Premier League per la distanza e la precisione del tiro."
   ],
