   "id": "zacc7b607",
   "sez": "ambiente",
   "titolo": "Al via la Cop17 sulla biodiversità a Erevan, tra bilanci e nuovi finanziamenti",
   "orig": "COP17: The world has a plan to save nature. Is it working?",
   "lead": "Quasi 200 Stati si riuniscono a Erevan, in Armenia, dal 19 al 30 ottobre per la Cop17 sulla biodiversità, chiamata a verificare i progressi rispetto ai 23 obiettivi fissati alla Cop15 del 2022, tra cui la protezione del 30% delle terre e dei mari entro il 2030. Al centro dei negoziati ci sono i finanziamenti tra paesi del Nord e del Sud e il ruolo delle comunità indigene. Secondo gli organizzatori, per ogni dollaro investito nella protezione della natura ne vengono spesi 30 per la sua distruzione. Lo riferiscono UN News, The Guardian e Le Monde.",
   "more": [
    "La Convenzione sulla diversità biologica è il trattato Onu che dal 1992 guida gli impegni globali per proteggere ecosistemi e specie; la Cop15 del 2022 ha fissato il quadro \"30x30\" per tutelare il 30% del pianeta entro il 2030, oggi oggetto di verifica."
   ],
