   "id": "zc1a350d4",
   "sez": "salute",
   "titolo": "Uno studio collega l'uso di antibiotici in infanzia a maggior rischio di sindrome del colon irritabile",
   "orig": "Antibiotic use from childhood linked to higher odds of IBS in young adulthood",
   "lead": "Uno studio presentato alla UEG Week 2026 ha rilevato che l'uso di antibiotici dall'infanzia fino alla prima età adulta è associato a una maggiore probabilità di sviluppare la sindrome dell'intestino irritabile (IBS) a 24 anni. Secondo la ricerca, il rischio aumenta con il numero di prescrizioni di antibiotici ricevute nel corso della vita. Lo studio è stato presentato durante la conferenza europea di gastroenterologia tenutasi a Barcellona. Lo riferisce Medical Xpress.",
   "more": [
    "La sindrome dell'intestino irritabile (IBS) è un disturbo cronico che colpisce l'apparato digestivo, causando dolore addominale e alterazioni dell'alvo. Gli antibiotici possono alterare il microbiota intestinale, l'insieme di batteri che popolano l'intestino, e diversi studi hanno indagato il legame tra queste alterazioni e l'insorgenza di disturbi gastrointestinali funzionali."
   ],
