   "titolo": "Figi, la ministra Tabuya: la data del referendum del 9 dicembre non è vincolante",
   "orig": "December 9 referendum date is proposed, not binding; Tabuya",
   "lead": "Nelle Figi la ministra per il Cambiamento Climatico e l'Informazione Lynda Tabuya ha difeso l'annuncio del primo ministro sulla data del 9 dicembre per un referendum, precisando che si tratta di una proposta non vincolante, pensata per aiutare governo e funzionari elettorali a prepararsi, senza bypassare le procedure legali. La precisazione arriva dopo le critiche del leader del Social Democratic Liberal Party, Aseri Radrodro, che aveva messo in dubbio la legittimità dell'annuncio. Lo riferisce FBC News.",
