   "id": "z1880ab4c",
   "sez": "viaggi",
   "titolo": "Klook ritira la quotazione negli Stati Uniti citando le condizioni di mercato",
   "orig": "Klook Withdraws U.S. IPO, Citing Market Conditions",
   "lead": "La piattaforma di esperienze di viaggio Klook ha ritirato la propria richiesta di quotazione in borsa negli Stati Uniti, citando le attuali condizioni di mercato come motivo della decisione. Secondo la testata, il settore delle esperienze turistiche resta uno dei meno digitalizzati del mondo dei viaggi, e questo rappresenta ancora un ampio margine di crescita per l'azienda. La concorrenza di piattaforme come Viator e GetYourGuide, però, è già consapevole di questa opportunità. Lo riferisce Skift.",
   "more": [
    "Klook è una piattaforma asiatica specializzata nella prenotazione di esperienze turistiche, attività e tour, che compete con operatori globali come Viator e GetYourGuide. Una IPO (offerta pubblica iniziale) è il processo con cui un'azienda privata inizia a quotarsi in borsa raccogliendo capitali dagli investitori."
   ],
