   "id": "z854acda9",
   "sez": "tech",
   "titolo": "ASML punta sul bonding ibrido, adottato anche da aziende cinesi del chip",
   "orig": "ASML eyes hybrid bonding, report finds, as Chinese firms adopt chip packaging technique",
   "lead": "Il colosso olandese dei semiconduttori ASML si sta espandendo nella tecnologia di bonding ibrido di nuova generazione, una tecnica che crea connessioni elettriche dense unendo direttamente chip o wafer di silicio, secondo un nuovo rapporto. Anche importanti aziende cinesi stanno adottando questa tecnologia per migliorare le prestazioni dei chip. Tra dicembre 2022 e novembre 2024 ASML ha presentato 27 famiglie di brevetti legate a strumenti per il bonding ibrido, secondo un rapporto pubblicato da una società di ricerca specializzata nella catena di fornitura di semiconduttori e intelligenza artificiale. Lo riferisce South China Morning Post.",
   "more": [
    "Il bonding ibrido è una tecnica avanzata di assemblaggio dei chip che permette di impilare più strati di silicio con connessioni elettriche molto più dense rispetto ai metodi tradizionali, migliorando prestazioni e efficienza energetica dei semiconduttori usati in intelligenza artificiale e dispositivi avanzati. ASML è il principale fornitore mondiale di macchinari per la produzione di chip."
   ],
