   "id": "z35914989",
   "sez": "viaggi",
   "titolo": "Il Regno Unito punta a distribuire i turisti indiani fuori da Londra",
   "orig": "UK’s India Growth Plan Means Getting Travelers Out of London",
   "lead": "Il governo britannico vuole aumentare la spesa dei visitatori indiani fino a 2 miliardi di dollari entro il 2030, ma secondo gli analisti il vero problema non è attrarre più turisti dall'India, quanto convincere quelli già in arrivo a visitare anche le regioni oltre la capitale. Oggi il 94% dei voli diretti dall'India atterra a Londra, concentrando lì la maggior parte dei visitatori. Per raggiungere l'obiettivo di spesa, sostiene la testata, servirà sviluppare collegamenti aerei regionali e itinerari turistici pensati per invogliare i viaggiatori indiani a spostarsi anche in altre zone del Regno Unito. Lo riferisce Skift.",
   "more": [
    "Il turismo indiano in uscita è in forte crescita grazie all'aumento della classe media e alla maggiore disponibilità di voli internazionali. Molti paesi europei stanno cercando di attrarre questo mercato, considerato tra i più promettenti per i prossimi anni, puntando su marketing mirato e nuove rotte aeree dirette verso città diverse dalle capitali tradizionali."
   ],
