   "id": "z5976abf0",
   "sez": "manga",
   "titolo": "Il nuovo film live-action di Street Fighter debutta al primo posto negli Stati Uniti",
   "orig": "New Live-Action Street Fighter Film Opens at #1 in the U.S., Earns US$51 Million Globally",
   "lead": "Il nuovo film live-action basato sul videogioco Street Fighter ha debuttato al primo posto al box office statunitense, incassando circa 31 milioni di dollari negli Stati Uniti e 20,1 milioni di dollari in 65 mercati internazionali, per un totale globale stimato di 51 milioni di dollari. Il risultato segna un esordio positivo per la pellicola, tratta dalla celebre saga di videogiochi di combattimento prodotta da Capcom. Lo riferisce Anime News Network.",
   "more": [
    "Street Fighter è una delle serie di videogiochi di combattimento più longeve e popolari al mondo, lanciata da Capcom nel 1987. Negli anni ha generato numerosi adattamenti cinematografici e animati, oltre a un vasto seguito competitivo nei torneo di eSport internazionali."
   ],
