   "id": "z5783ebaf",
   "sez": "economia",
   "titolo": "Manovra, caccia a 13 miliardi di coperture mentre si attende flessibilità dall'Ue",
   "orig": "In attesa di più flessibilità dalla Ue è caccia a 13 miliardi di coperture",
   "lead": "Il governo italiano lavora alla prossima legge di bilancio, che vale complessivamente 23,5 miliardi di euro, ma deve ancora trovare circa 13 miliardi di coperture: circa 10 miliardi restano da individuare, oltre a quasi 14 miliardi già discussi. Nel frattempo l'esecutivo attende segnali di maggiore flessibilità da parte dell'Unione europea sui conti pubblici. Parallelamente, al Consiglio europeo il presidente ucraino Volodymyr Zelensky ha chiesto ai leader dell'Unione altri 70 miliardi di euro per affrontare le necessità del 2027, una richiesta che ha spiazzato i partner europei. Lo riferisce Il Messaggero.",
   "more": [
    "La legge di bilancio è il principale strumento con cui ogni anno il governo stabilisce entrate e spese pubbliche per l'anno successivo. Trovare le 'coperture', cioè le risorse necessarie a finanziare le misure previste, è spesso la fase più complessa della trattativa, soprattutto quando i margini di manovra concessi dalle regole europee sul debito sono limitati."
   ],
