   "sez": "mondo",
   "titolo": "Attacchi di drone bloccano due petroliere dirette in Kenya",
   "orig": "Drone strikes stall two fuel tankers bound for Kenya",
   "lead": "Due autocisterne di carburante dirette verso il Kenya sono state bloccate da attacchi con drone, in un contesto di crescenti tensioni tra Iran e Arabia Saudita. L'episodio, riportato da Daily Nation, non viene ulteriormente dettagliato nelle circostanze specifiche né nei responsabili, ma viene collegato al clima di tensione regionale tra i due paesi mediorientali. Lo riferisce Daily Nation.",
   "more": [
    "Le tensioni tra Iran e Arabia Saudita, due potenze rivali nella regione del Golfo, hanno storicamente avuto ripercussioni sulle rotte di approvvigionamento energetico internazionali, incluse quelle che attraversano aree strategiche come lo Stretto di Hormuz, fondamentale per il trasporto di petrolio verso l'Africa e l'Asia."
   ],
