   "titolo": "Come scegliere il bicchiere giusto per lo champagne",
   "orig": "Scegliere il bicchiere giusto per lo champagne con i consigli giusti",
   "lead": "La forma del bicchiere influisce sulla percezione di profumi, bollicine e sapore dello champagne: flûte o calice ampio fanno la differenza. La Cucina Italiana racconta questa scoperta fatta durante una degustazione speciale organizzata da Veuve Clicquot, seguita da un pranzo firmato dalla chef Jessica Rosval. Lo riferisce La Cucina Italiana.",
   "more": [
    "La scelta del bicchiere per il vino, incluso lo champagne, è oggetto di studio da parte di sommelier e produttori: la forma del calice può modificare la concentrazione degli aromi e la percezione delle bollicine, motivo per cui negli ultimi anni molte maison hanno iniziato a consigliare calici più ampi rispetto alla tradizionale flûte."
   ],
