   "lead": "Guabirá e Oriente Petrolero hanno chiuso 1-1 la 22ª giornata del campionato boliviano, in una partita giocata a Montero. Secondo Brújula Digital, l'attaccante di Guabirá Gustavo Peredo ha segnato tre gol, tutti annullati per fuorigioco, vivendo una giornata da dimenticare. Secondo El Deber, Mizael Pinto aveva aperto le marcature per l'Oriente Petrolero, mentre Milton Masiel ha pareggiato per i locali di Guabirá, che hanno chiuso la partita in dieci uomini.",
