   "titolo": "HD Hyundai testa una nave militare senza equipaggio al largo della California",
   "orig": "HD Hyundai tests uncrewed naval vessel off California coast",
   "lead": "Il costruttore navale sudcoreano HD Hyundai ha testato lunedì al largo di Long Beach, in California, le capacità autonome di una nave di superficie senza equipaggio, in collaborazione con l'azienda statunitense della difesa Anduril Industries. Secondo The Korea Herald, si tratta della prima dimostrazione di questo tipo condotta da un'azienda sudcoreana nelle acque statunitensi, parte della strategia dell'azienda per entrare nel crescente mercato della difesa navale negli Stati Uniti e nel mondo. Lo riferisce The Korea Herald.",
   "more": [
    "Le navi di superficie senza equipaggio sono considerate un settore in forte crescita nella difesa navale, utilizzate per compiti di sorveglianza, ricognizione e potenzialmente combattimento, riducendo i rischi per il personale. Diversi paesi, inclusi Stati Uniti e Corea del Sud, stanno investendo in queste tecnologie per rafforzare le proprie capacità marittime."
   ],
