   "sez": "salute",
   "titolo": "Cambiamenti immunitari possono segnalare la malattia infiammatoria intestinale fino a 10 anni prima della diagnosi",
   "orig": "Immune changes could signal inflammatory bowel disease up to 10 years before diagnosis",
   "lead": "Uno studio su larga scala presentato al congresso UEG Week 2026 ha individuato pattern distinti di anticorpi rilevabili fino a dieci anni prima della diagnosi di malattia infiammatoria intestinale (IBD). La scoperta potrebbe aprire nuove strade per l'identificazione precoce del rischio e fornire indicazioni utili sul possibile andamento futuro della malattia nei pazienti. Lo riferisce Medical Xpress.",
   "more": [
    "Le malattie infiammatorie intestinali, come il morbo di Crohn e la colite ulcerosa, sono patologie croniche del tratto digestivo la cui origine è legata a fattori genetici, immunitari e ambientali. Individuare segnali precoci, come specifici anticorpi nel sangue, potrebbe permettere diagnosi più rapide e trattamenti tempestivi, riducendo le complicanze a lungo termine."
   ],
