   "id": "z3a3b7510",
   "sez": "dibattito",
   "titolo": "Austria, la ministra difende l'accordo sul bilancio delle università",
   "orig": "Holzleitner verteidigt Unibudgeteinigung",
   "lead": "In Austria la ministra della Scienza Eva-Maria Holzleitner (SPÖ) ha difeso domenica, durante il programma televisivo ZIB2, l'accordo sul bilancio per le università. I 16 miliardi di euro previsti per il periodo 2028-2030 sono, secondo la ministra, superiori a quanto inizialmente stabilito dal governo, garantendo un \"livello stabile\" di finanziamento e assicurando il pagamento degli stipendi dei medici. La Conferenza delle Università austriache (uniko) ha invece avvertito di conseguenze \"enormemente negative\" per università, studenti e ricercatori, sostenendo che i fondi non sarebbero sufficienti.",
   "more": [
    "In molti paesi europei il finanziamento pubblico delle università è oggetto di tensioni tra governi, che devono gestire bilanci statali limitati, e le istituzioni accademiche, che richiedono risorse adeguate per la ricerca e la didattica. In Austria il sistema universitario è in gran parte pubblico, e le decisioni sui finanziamenti pluriennali influenzano stipendi, assunzioni e qualità della ricerca."
   ],
