   "sez": "dibattito",
   "titolo": "La battaglia sull'energia nell'UE e l'Italia in difficoltà",
   "orig": "The EU energy battle rages on — and Italy is losing",
   "lead": "A Bruxelles l'Unione Europea ha approvato misure temporanee di sollievo sulle bollette energetiche, ma la premier italiana Giorgia Meloni non è riuscita a ottenere modifiche al sistema di scambio delle emissioni (ETS), secondo quanto riporta la Repubblica. Il governo italiano starebbe ora spingendo per ottenere maggiore flessibilità sul deficit nazionale, in un confronto che vede l'Italia in una posizione di debolezza rispetto ad altri paesi membri nella trattativa sulle politiche energetiche europee.",
   "more": [
    "Il sistema di scambio delle quote di emissione (ETS) dell'UE impone alle imprese di acquistare permessi per inquinare, con l'obiettivo di incentivare la riduzione delle emissioni, ma genera anche costi che si riflettono sui prezzi dell'energia. Diversi governi, tra cui quello italiano, chiedono da tempo modifiche al meccanismo per attenuare l'impatto sui consumatori e sulle imprese energivore."
   ],
