   "id": "z71b17aca",
   "sez": "salute",
   "titolo": "La vita sospesa di un malato di cancro, tra attese e accesso alle cure",
   "orig": "La vita sospesa di un malato di cancro. E tanto incide l’attesa per l’accesso alle cure",
   "lead": "Un cittadino italiano racconta su Il Fatto Quotidiano la propria esperienza di malattia oncologica, diagnosticata il 21 febbraio 2018 e operata il 5 aprile dello stesso anno, dopo otto anni di assenza di malattia. Le ultime analisi indicano una probabile ripresa della patologia, e la verifica definitiva è fissata per il 4 novembre 2026. Il racconto descrive come i tempi di attesa per accertamenti e cure incidano pesantemente sulla vita quotidiana dei pazienti oncologici in Italia. Lo riferisce Il Fatto Quotidiano.",
   "more": [
    "I tempi di attesa per esami diagnostici e trattamenti oncologici sono un tema ricorrente nel sistema sanitario italiano, dove liste d'attesa lunghe possono influire sull'ansia dei pazienti e, in alcuni casi, sull'efficacia delle cure. Associazioni di pazienti chiedono da anni percorsi prioritari per le patologie oncologiche."
   ],
   "fonti": [
    {
     "n": "Il Fatto Quotidiano",
     "p": "IT",
     "c": "Roma",
     "u": "https://www.ilfattoquotidiano.it/2026/10/19/liste-attesa-sanita-paziente-oncologico-notizie/8539175/",
     "angolo": "",
     "atlas": "Italy",
     "t": "2026-10-19T04:40+00:00"
    }
   ],
   "data": "19 ott",
