   "sez": "prima",
   "titolo": "Trump difende l'esenzione dalle sanzioni alla Russia e attacca Zelensky",
   "orig": "Trump defends Russia sanctions waivers, accuses Zelenskyy of 'prolonging war'",
   "lead": "Il presidente statunitense Donald Trump ha difeso la decisione di esentare la Russia da nuove sanzioni, firmando un ordine esecutivo che definisce la misura «nell'interesse nazionale» degli Stati Uniti. Trump ha inoltre accusato il presidente ucraino Volodymyr Zelensky di non voler porre fine alla guerra, rinnovando le tensioni sulla politica americana verso Mosca mentre attacchi mortali russi hanno gettato nel buio parti dell'Ucraina. Le dichiarazioni arrivano mentre Zelensky è in contatto con gli inviati di Washington per discutere i prossimi passi del conflitto.",
   "more": [
    "Le sanzioni in questione, previste da una legislazione sostenuta anche dal senatore Lindsey Graham, erano destinate a colpire la Russia per la guerra in Ucraina. L'esenzione firmata da Trump ne sospende l'applicazione, suscitando critiche da Kiev e dagli alleati europei degli Stati Uniti."
   ],
