   "id": "z6c02f0a8",
   "sez": "prima",
   "titolo": "La crescita cinese accelera al 4,5%, sostenuta dal boom dell'export legato all'IA",
   "orig": "China's growth accelerates as AI export boom outweighs domestic weakness",
   "lead": "L'economia cinese ha registrato nel terzo trimestre una crescita del 4,5%, superando le previsioni degli analisti e accelerando rispetto al 4,3% del trimestre precedente, il ritmo più lento in oltre tre anni. Il dato, diffuso lunedì dalle autorità di Pechino, è stato sostenuto da esportazioni robuste, in particolare legate all'intelligenza artificiale, che hanno compensato la debolezza della domanda interna. Il risultato pone la seconda economia mondiale sulla buona strada per raggiungere l'obiettivo di crescita annuale, pur restando nella parte bassa del target fissato dal governo.",
   "more": [
    "Il Prodotto interno lordo trimestrale è l'indicatore chiave usato da Pechino per misurare l'andamento dell'economia nazionale. Le tensioni commerciali internazionali e l'incertezza sulla domanda di tecnologie legate all'intelligenza artificiale restano fattori di rischio per le prospettive future del paese."
   ],
