   "sez": "italia",
   "titolo": "Nuovi scontri a Milano, Meloni convoca vertice sulla sicurezza",
   "orig": "A Milano ancora scontri, Meloni convoca il vertice sulla sicurezza",
   "lead": "Il centro di Milano è stato di nuovo teatro di guerriglia urbana, con lanci di oggetti e petardi contro le forze dell'ordine, che hanno risposto con idranti e lacrimogeni. Sono oltre 200 i fermati, l'80% dei quali minorenni. La premier Giorgia Meloni ha convocato per lunedì un vertice sull'ordine pubblico, mentre è emerso un confronto tra il sindaco Giuseppe Sala e il ministro dell'Interno Matteo Piantedosi sull'impiego degli agenti. Sala ha espresso «condanna totale» per chi compie «azioni criminali». Lo riferisce l'ANSA.",
   "more": [
    "Il vertice sull'ordine pubblico è una riunione istituzionale convocata dal governo per coordinare le misure di sicurezza tra ministero dell'Interno, prefettura e forze di polizia. Il confronto tra sindaco e ministro riguarda le competenze e le responsabilità nella gestione degli agenti sul territorio durante le manifestazioni."
   ],
