     "t": "Racconta scontri 'pitched battles' nel quinto giorno di proteste, con molotov, lacrimogeni e, per la prima volta, pallottole di gomma. Cita 80 denunce, intervista manifestanti come George e Klea, e ricostruisce lo scandalo che coinvolge la ex capo dei servizi segreti Hyseni e l'imprenditore Agasi.",
