     "t": "Centra il racconto sulle proteste studentesche per i costi dell'istruzione, con incendi a un edificio governativo e due banche; cita 23 poliziotti e 6 feriti, 35 arresti. Riporta dichiarazioni del presidente Begaj, della vice premier Koçiu e la preoccupazione dell'UE per 'eccessiva violenza' della polizia.",
