   "divergono": "Folha de S.Paulo si distingue nettamente dalle altre testate per il taglio: non narra il clima dello scontro ma verifica puntualmente le cifre citate da Lula e Bolsonaro, correggendo dati su PIL, inflazione e viaggi presidenziali, aspetto assente negli altri articoli. Le altre testate (RTÉ, LRT, The Straits Times) condividono quasi integralmente le stesse citazioni e lo stesso sondaggio (51% Bolsonaro, 49% Lula), mentre Al Jazeera riporta percentuali diverse riferite al primo turno (47% contro 45%). South China Morning Post offre il resoconto più sintetico, senza dettagli sulle manifestazioni di piazza presenti invece in RTÉ, LRT e The Straits Times."
